    // Web Audio Sound Effects for Kids
    let audioCtx = null;
    let soundOn = true;

    function playTone(type) {
      if (!soundOn) return;
      try {
        const AudioContext = window.AudioContext || window.webkitAudioContext;
        if (!audioCtx && AudioContext) audioCtx = new AudioContext();
        if (!audioCtx) return;
        if (audioCtx.state === 'suspended') audioCtx.resume();

        const now = audioCtx.currentTime;
        const notes = type === 'correct' ? [523.25, 659.25, 783.99] : type === 'finish' ? [523.25, 659.25, 783.99, 1046.5] : [240, 190];
        notes.forEach((freq, idx) => {
          const osc = audioCtx.createOscillator();
          const gain = audioCtx.createGain();
          osc.type = type === 'wrong' ? 'sawtooth' : 'triangle';
          osc.frequency.setValueAtTime(freq, now + idx * 0.09);
          gain.gain.setValueAtTime(0.05, now + idx * 0.09);
          gain.gain.exponentialRampToValueAtTime(0.0001, now + idx * 0.09 + 0.25);
          osc.connect(gain);
          gain.connect(audioCtx.destination);
          osc.start(now + idx * 0.09);
          osc.stop(now + idx * 0.09 + 0.26);
        });
      } catch (e) {}
    }

    function toggleSound() {
      soundOn = !soundOn;
      document.getElementById('btn-sound').textContent = soundOn ? '🔊 Suara Aktif' : '🔇 Bisu';
    }

    function deduplicateQuestions(list) {
      if (!Array.isArray(list)) return [];
      const seen = new Set();
      const result = [];
      list.forEach(q => {
        const key = (q.subject || '') + '||' + (q.question || '').toLowerCase().trim().replace(/^[0-9]+[\.\)]\s*/, '');
        if (!seen.has(key)) {
          seen.add(key);
          result.push(q);
        }
      });
      return result;
    }

    function loadData() {
      try {
        const rawQ = localStorage.getItem(STORAGE_KEY_Q);
        questions = rawQ ? JSON.parse(rawQ) : JSON.parse(JSON.stringify(window.DEFAULT_QUESTIONS_SD6));
      } catch (e) {
        questions = JSON.parse(JSON.stringify(window.DEFAULT_QUESTIONS_SD6));
      }
      const prevLen = questions.length;
      questions = deduplicateQuestions(questions);
      if (questions.length !== prevLen) {
        saveData();
      }

      try {
        const rawS = localStorage.getItem(STORAGE_KEY_STATS);
        if (rawS) studentStats = JSON.parse(rawS);
      } catch (e) {}
    }

    function saveData() {
      try {
        localStorage.setItem(STORAGE_KEY_Q, JSON.stringify(questions));
        localStorage.setItem(STORAGE_KEY_STATS, JSON.stringify(studentStats));
      } catch (e) {}
    }

    function resetDefaultData() {
      questions = JSON.parse(JSON.stringify(window.DEFAULT_QUESTIONS_SD6));
      saveData();
      refreshAll();
    }

